                i = j;
            } else {
                replaced.push(c);
                i+=1;
            }
        }

        // Now evaluate arithmetic expression with + - * / % and parentheses
        // Use simple shunting-yard or recursive

        fn eval_expr(s: &str) -> Result<i64, String> {
            // Remove spaces
            let s = s.replace(" ", "");
            if s.is_empty() { return Ok(0); }

            // We'll use recursive parsing with index
            fn parse_expr(chars: &[char], pos: &mut usize) -> Result<i64, String> {
                let mut value = parse_term(chars, pos)?;
                while *pos < chars.len() {
                    let op = chars[*pos];
                    if op == '+' || op == '-' {
                        *pos += 1;
                        let rhs = parse_term(chars, pos)?;
                        if op == '+' {
                            value = value + rhs;
                        } else {
                            value = value - rhs;
                        }
                    } else {
                        break;
                    }
                }
                Ok(value)
            }
            fn parse_term(chars: &[char], pos: &mut usize) -> Result<i64, String> {
                let mut value = parse_factor(chars, pos)?;
                while *pos < chars.len() {
                    let op = chars[*pos];
                    if op == '*' || op == '/' || op == '%' {
                        *pos += 1;
                        let rhs = parse_factor(chars, pos)?;
                        if op == '*' {
                            value = value * rhs;
                        } else if op == '/' {
                            if rhs == 0 {
                                return Err("divide by zero".to_string());
                            }
                            value = value / rhs;
                        } else {
                            if rhs == 0 {
                                return Err("divide by zero".to_string());
                            }
                            value = value % rhs;
                        }
                    } else {
                        break;
                    }
                }
                Ok(value)
            }
            fn parse_factor(chars: &[char], pos: &mut usize) -> Result<i64, String> {
                if *pos >= chars.len() {
                    return Ok(0);
                }
                if chars[*pos] == '(' {
                    *pos += 1;
                    let val = parse_expr(chars, pos)?;
                    if *pos < chars.len() && chars[*pos] == ')' {
                        *pos += 1;
                    }
                    Ok(val)
                } else if chars[*pos] == '-' {
                    *pos += 1;
                    let val = parse_factor(chars, pos)?;
                    Ok(-val)
                } else if chars[*pos].is_digit(10) {
                    let mut num = 0i64;
                    while *pos < chars.len() && chars[*pos].is_digit(10) {
                        num = num*10 + (chars[*pos] as i64 - '0' as i64);
                        *pos += 1;
                    }
                    Ok(num)
                } else {
                    // unexpected char, treat as 0
                    *pos += 1;
                    Ok(0)
                }
            }

            let chars: Vec<char> = s.chars().collect();
            let mut pos = 0;
            let res = parse_expr(&chars, &mut pos)?;
            Ok(res)
        }

        eval_expr(&replaced)
    }

