// Very simplistic tokenization

fn tokenize(input: &str) -> Vec<String> {
    // Split into tokens respecting quotes, handling operators ; && || | & ( ) { } < > >> << etc
    let mut tokens = Vec::new();
    let mut current = String::new();
    let mut in_single = false;
    let mut in_double = false;
    let mut chars = input.chars().peekable();

    while let Some(c) = chars.next() {
        if in_single {
            if c == '\'' {
                in_single = false;
                current.push(c);
                tokens.push(current.clone());
                current.clear();
            } else {
                current.push(c);
            }
            continue;
        }
        if in_double {
            if c == '"' {
                in_double = false;
                current.push(c);
                tokens.push(current.clone());
                current.clear();
            } else if c == '\\' {
                // escaped
                if let Some(next) = chars.next() {
                    current.push(c);
                    current.push(next);
                }
            } else {
                current.push(c);
            }
            continue;
        }

        match c {
            '\'' => {
                if !current.is_empty() {
                    tokens.push(current.clone());
                    current.clear();
                }
                in_single = true;
                current.push(c);
            },
            '"' => {
                if !current.is_empty() {
                    tokens.push(current.clone());
                    current.clear();
                }
                in_double = true;
                current.push(c);
            },
            ';' | '&' | '|' | '(' | ')' | '{' | '}' | '<' | '>' => {
                if !current.is_empty() {
                    tokens.push(current.clone());
                    current.clear();
                }
                // Check for double operators
                if c == '&' {
                    if let Some('&') = chars.peek() {
                        chars.next();
                        tokens.push("&&".to_string());
                    } else {
                        tokens.push("&".to_string());
                    }
                } else if c == '|' {
                    if let Some('|') = chars.peek() {
                        chars.next();
                        tokens.push("||".to_string());
                    } else {
                        tokens.push("|".to_string());
                    }
                } else if c == '>' {
                    if let Some('>') = chars.peek() {
                        chars.next();
                        tokens.push(">>".to_string());
                    } else if let Some('&') = chars.peek() {
                        // check for >& etc
                        // peek further
                        // For simplicity, we will handle >&2 as separate tokens? Actually >& is operator
                        // We'll look ahead for "&"
                        chars.next();
                        // check next char is digit?
                        if let Some('2') = chars.peek() {
                            //  >&2
                            chars.next();
                            tokens.push(">&2".to_string());
                        } else {
                            tokens.push(">".to_string());
                            tokens.push("&".to_string());
                        }
                    } else {
                        tokens.push(">".to_string());
                    }
                } else if c == '<' {
                    if let Some('<') = chars.peek() {
                        chars.next();
                        tokens.push("<<".to_string());
                    } else {
                        tokens.push("<".to_string());
                    }
                } else {
                    tokens.push(c.to_string());
                }
            },
            ' ' | '\t' | '\n' => {
                if !current.is_empty() {
                    tokens.push(current.clone());
                    current.clear();
                }
                if c == '\n' {
                    tokens.push("\n".to_string());
                }
            },
            _ => {
                current.push(c);
            }
        }
    }
    if !current.is_empty() {
        tokens.push(current);
    }
    tokens
}

