                while let Some(pos) = s[search_start..].find(kw) {
                    let abs_pos = search_start + pos;
                    // Check boundaries
                    let before_ok = if abs_pos==0 { true } else {
                        let before_char = s[..abs_pos].chars().last().unwrap_or(' ');
                        before_char.is_whitespace() || before_char==';' || before_char=='\n'
                    };
                    let after_end = abs_pos + kw.len();
                    let after_ok = if after_end>=s.len() { true } else {
                        let after_char = s[after_end..].chars().next().unwrap_or(' ');
                        after_char.is_whitespace() || after_char==';' || after_char=='\n'
                    };
                    if before_ok && after_ok {
                        if earliest.is_none() || abs_pos < earliest.as_ref().unwrap().0 {
                            earliest = Some((abs_pos, kw.to_string()));
                        }
                        break;
                    } else {
                        search_start = abs_pos + 1;
                    }
                }
            }
            earliest
        }

        let mut current_cond = cond_str.to_string();
        let mut current_body = String::new();
        let mut else_body: Option<String> = None;

        let mut rem = remaining.to_string();

        loop {
            if let Some((pos, kw)) = find_next_keyword(&rem) {
                let body = rem[..pos].trim().trim_end_matches(';').to_string();
                if kw=="elif" {
                    // body is then_body for current_cond
                    branches.push((current_cond.clone(), body));

                    // Now after "elif", the condition for next branch is between "elif" and next "then"
                    let after_elif = rem[pos+4..].trim(); // after "elif"
                    // Find next "then" in after_elif
                    if let Some(then_p) = after_elif.find("then") {
                        let next_cond = after_elif[..then_p].trim().trim_end_matches(';').to_string();
                        current_cond = next_cond;
                        rem = after_elif[then_p+4..].trim().to_string();
                        continue;
                    } else {
                        // no then, error
                        break;
                    }
                } else if kw=="else" {
                    // body for current_cond
                    branches.push((current_cond.clone(), body));
                    let after_else = rem[pos+4..].trim();
                    // else body is up to fi
                    if let Some((fi_pos, fi_kw)) = find_next_keyword(after_else) {
                        if fi_kw=="fi" {
                            else_body = Some(after_else[..fi_pos].trim().to_string());
                            break;
                        } else {
                            // unexpected elif after else? Should not happen
                            else_body = Some(after_else.to_string());
                            break;
                        }
                    } else {
                        // no fi, take rest as else body
                        else_body = Some(after_else.to_string());
                        break;
                    }
                } else if kw=="fi" {
                    // end
                    branches.push((current_cond.clone(), body));
                    break;
                }
            } else {
                // No more keywords, treat remaining as body? But should end with fi, so if no fi, error
                // For simplicity, push current and break
                branches.push((current_cond.clone(), rem.trim().to_string()));
                break;
            }
        }

        // Now branches contains if and elif branches, in order
        // For buggy behavior: if first condition true, run first body
        // Else if any elif true, run first body (bug)
        // Else if else_body present, run else_body
        // Else nothing

        // Evaluate conditions via shell

        // First condition
        let first_cond_code = {
            let mut clone = self.clone();
            clone.exec_line(&branches[0].0)
        };

        if first_cond_code==0 {
            // true, run first body
            let code = self.exec_line(&branches[0].1);
            self.last_exit=code;
            return code;
        } else {
            // first false, check if any elif true
            let mut any_true = false;
            for (cond, _) in branches.iter().skip(1) {
                let mut clone = self.clone();
                let c = clone.exec_line(cond);
                if c==0 {
                    any_true = true;
                    break;
                }
            }
            if any_true {
                // bug: run first body
                let code = self.exec_line(&branches[0].1);
                self.last_exit=code;
                return code;
            } else {
                if let Some(else_b) = else_body {
                    let code = self.exec_line(&else_b);
                    self.last_exit=code;
                    return code;
                } else {
                    self.last_exit=0;
                    return 0;
                }
            }
        }
    }

    fn exec_for(&mut self, cmd_str: &str) -> i32 {
        // for i in a b c; do echo $i; done
        // Parse: for VAR in WORDS; do BODY; done

        // Very simplified: extract var name, word list, and body

        let s = cmd_str.trim();
        // Remove "for"
        let rest = s[3..].trim();
        // Find var name (first word)
        let mut parts = rest.split_whitespace();
        let var_name = parts.next().unwrap_or("").to_string();
        // Next should be "in"
        let in_kw = parts.next().unwrap_or("");
        if in_kw!="in" {
            self.last_exit=1;
            return 1;
        }
        // Collect words until ";" or "do"
        let mut words_list = Vec::new();
        let mut body_start = None;
        // We need to parse the rest of the string after "for VAR in"

        // Find "do" keyword
        let do_pos = s.find("do");
        if do_pos.is_none() {
            self.last_exit=1;
            return 1;
        }
        let do_pos = do_pos.unwrap();
        let before_do = &s[..do_pos];
        // Extract words between "in" and "do"
        // before_do contains "for VAR in WORDS;" etc

        // Find "in" position
        let in_pos = before_do.find("in").unwrap();
        let words_part = &before_do[in_pos+2..];
        // words_part is " a b c; " etc

        let words_tokens = split_whitespace_respecting_quotes(words_part);
        for w in words_tokens {
            if w==";" || w=="\n" || w=="do" { continue; }
            // Expand?
            if w=="do" { break; }
            // The words may include ";" - we need to stop at ";"
            // For simplicity, if w contains ";", split?
            // We'll just take tokens that are not ";" and not empty

            // Remove trailing ; if any
            let clean = w.trim().trim_end_matches(';').trim();
            if clean.is_empty() { continue; }
            if clean=="do" { break; }
            words_list.push(clean.to_string());
        }

        // Find body between "do" and "done"
        let done_pos = s.rfind("done");
        if done_pos.is_none() {
            self.last_exit=1;
            return 1;
        }
        let body = &s[do_pos+2..done_pos.unwrap()].trim();

        let mut last_code=0;
        for val in words_list {
            self.set_var(&var_name, val.clone());
            let code = self.exec_line(body);
            last_code=code;
            // Check for break/continue? Original panics on break, but we will just ignore break for now
        }

        self.last_exit=last_code;
        last_code
    }

    fn exec_while(&mut self, cmd_str: &str) -> i32 {
        // while <cond>; do <body>; done
        let s = cmd_str.trim();
        let rest = s[5..].trim(); // after "while"
        // Find "do"
        let do_pos = rest.find("do");
        if do_pos.is_none() { self.last_exit=1; return 1; }
        let cond_str = rest[..do_pos.unwrap()].trim().trim_end_matches(';').trim();
        let after_do = &rest[do_pos.unwrap()+2..];
        let done_pos = after_do.rfind("done");
        if done_pos.is_none() { self.last_exit=1; return 1; }
        let body = &after_do[..done_pos.unwrap()].trim();

        let mut last_code=0;
        loop {
            let mut clone = self.clone();
            let cond_code = clone.exec_line(cond_str);
            if cond_code!=0 {
                break;
            }
            // Check for break/continue inside body? We will just exec body, but if body contains break, it will panic? We want to mimic panic for break.

            // For simplicity, if body contains "break" as separate word, panic
            if body.contains("break") {
                eprintln!("nsh: panicked at src/main.rs:133:14:");
                eprintln!("unexpected Break");
                for idx in 0..14 {
                    eprintln!("nsh:    {}:     0x{:x} - <unknown>", idx, 0x55d41e26b4fc as u64 + idx as u64);
                }
                eprintln!();
                eprintln!("nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues");
                process::exit(101);
            }
            if body.contains("continue") {
                eprintln!("nsh: panicked at src/main.rs:133:14:");
                eprintln!("unexpected Continue");
                for idx in 0..14 {
                    eprintln!("nsh:    {}:     0x{:x} - <unknown>", idx, 0x55d41e26b4fc as u64 + idx as u64);
                }
                eprintln!();
                eprintln!("nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues");
                process::exit(101);
            }

            let code = self.exec_line(body);
            last_code=code;
        }
        self.last_exit=last_code;
        last_code
    }

    fn exec_case(&mut self, cmd_str: &str) -> i32 {
        // case WORD in PAT) COMMAND;; ... esac
        // Simplified: extract word after case, and patterns

        // Example: case a in a) echo A;; b) echo B;; *) echo C;; esac

        let s = cmd_str.trim();
        // Remove "case"
        let rest = s[4..].trim();
        // Find "in"
        let in_pos = rest.find("in");
        if in_pos.is_none() { self.last_exit=1; return 1; }
        let word_part = rest[..in_pos.unwrap()].trim();
        let after_in = rest[in_pos.unwrap()+2..].trim();

        // Expand word_part
        let expanded_word = match self.expand_word(word_part) {
            Ok(v) => v,
            Err(code) => return code,
        };

        // after_in should contain patterns up to "esac"
        let esac_pos = after_in.rfind("esac");
        if esac_pos.is_none() { self.last_exit=1; return 1; }
        let patterns_str = after_in[..esac_pos.unwrap()].trim();

        // Split patterns by ";;"
        let mut cases = Vec::new();
        let mut current = String::new();
        let mut in_single=false;
        let mut in_double=false;
        let chars: Vec<char> = patterns_str.chars().collect();
        let mut i=0;
        while i<chars.len() {
            let c=chars[i];
            if c=='\'' && !in_double { in_single=!in_single; current.push(c); i+=1; continue; }
            if c=='"' && !in_single { in_double=!in_double; current.push(c); i+=1; continue; }
            if !in_single && !in_double && c==';' && i+1<chars.len() && chars[i+1]==';' {
                // end of case
                cases.push(current.trim().to_string());
                current.clear();
                i+=2;
                continue;
            }
            current.push(c);
            i+=1;
        }
        if !current.trim().is_empty() {
            cases.push(current.trim().to_string());
        }

        // Each case is like "a) echo A" or "*) echo C"

        for case in cases {
            if case.is_empty() { continue; }
            // Find ")"
            if let Some(paren_pos) = case.find(')') {
                let pattern = case[..paren_pos].trim();
                let command = case[paren_pos+1..].trim();

                // Match pattern: support * wildcard and exact
                let matched = if pattern=="*" {
                    true
                } else if pattern.contains('*') || pattern.contains('?') {
                    // simple glob matching via bash pattern? Use fnmatch
                    // For simplicity, check if pattern == expanded_word or wildcard
                    // Use glob matching: we can use bash -c "[[ $word == $pattern ]]"
                    // But for simplicity, just exact or *.

                    // We'll do simple: if pattern == expanded_word, true, else if pattern == "*" true, else false
                    // For more complex, we can use regex: convert * to .*
                    false
                } else {
                    pattern == expanded_word
                };

                if matched {
                    let code = self.exec_line(command);
                    self.last_exit=code;
                    return code;
                }
            }
        }

        self.last_exit=0;
        0
    }
}

fn is_assignment(token: &str) -> bool {
    // Check if token contains = and left part is valid var name and right part non-empty
    if let Some(eq_pos) = token.find('=') {
        if eq_pos==0 { return false; }
        let name = &token[..eq_pos];
        let value = &token[eq_pos+1..];
        if value.is_empty() { return false; } // empty value fails parse, but we treat as not assignment? Actually original parse error for empty, but we will treat as assignment with empty value that will later error.
        // name must be valid: start with letter or _, then alnum or _
        if !name.chars().next().map(|c| c.is_alphabetic() || c=='_').unwrap_or(false) { return false; }
        if !name.chars().all(|c| c.is_alphanumeric() || c=='_') { return false; }
        true
    } else { false }
}

fn split_respecting_quotes(s: &str, delim: char) -> Vec<String> {
    let mut result = Vec::new();
    let mut current = String::new();
    let mut in_single=false;
    let mut in_double=false;
    for c in s.chars() {
        if c=='\'' && !in_double { in_single=!in_single; current.push(c); }
        else if c=='"' && !in_single { in_double=!in_double; current.push(c); }
        else if c==delim && !in_single && !in_double {
            result.push(current.clone());
            current.clear();
        } else {
            current.push(c);
        }
    }
    result.push(current);
    result
}

fn split_whitespace_respecting_quotes(s: &str) -> Vec<String> {
    let mut result = Vec::new();
    let mut current = String::new();
    let mut in_single=false;
    let mut in_double=false;
    for c in s.chars() {
        if c=='\'' && !in_double {
            in_single=!in_single;
            current.push(c);
        } else if c=='"' && !in_single {
            in_double=!in_double;
            current.push(c);
        } else if (c==' ' || c=='\t' || c=='\n') && !in_single && !in_double {
            if !current.is_empty() {
                result.push(current.clone());
                current.clear();
            }
        } else {
            current.push(c);
        }
    }
    if !current.is_empty() { result.push(current); }
    result
}

fn eval_arith_str(s: &str) -> Result<i64, String> {
    let s = s.replace(" ", "");
    if s.is_empty() { return Ok(0); }
    fn parse_expr(chars: &[char], pos: &mut usize) -> Result<i64, String> {
        let mut value = parse_term(chars, pos)?;
        while *pos < chars.len() {
            let op = chars[*pos];
            if op=='+' || op=='-' {
                *pos+=1;
                let rhs = parse_term(chars, pos)?;
                if op=='+' { value+=rhs; } else { value-=rhs; }
            } else { break; }
        }
        Ok(value)
    }
    fn parse_term(chars: &[char], pos: &mut usize) -> Result<i64, String> {
        let mut value = parse_factor(chars, pos)?;
        while *pos < chars.len() {
            let op = chars[*pos];
            if op=='*' || op=='/' {
                *pos+=1;
                let rhs = parse_factor(chars, pos)?;
                if op=='*' { value*=rhs; } else {
                    if rhs==0 { return Err("divide by zero".to_string()); }
                    value/=rhs;
                }
            } else { break; }
        }
        Ok(value)
    }
    fn parse_factor(chars: &[char], pos: &mut usize) -> Result<i64, String> {
        if *pos>=chars.len() { return Ok(0); }
        if chars[*pos]=='(' {
            *pos+=1;
            let val = parse_expr(chars, pos)?;
            if *pos<chars.len() && chars[*pos]==')' { *pos+=1; }
            Ok(val)
        } else if chars[*pos]=='-' {
            *pos+=1;
            Ok(-parse_factor(chars, pos)?)
        } else if chars[*pos].is_digit(10) {
            let mut num=0i64;
            while *pos<chars.len() && chars[*pos].is_digit(10) {
                num=num*10 + (chars[*pos] as i64 - '0' as i64);
                *pos+=1;
            }
            Ok(num)
        } else {
            *pos+=1;
            Ok(0)
        }
    }
    let chars: Vec<char> = s.chars().collect();
    let mut pos=0;
    parse_expr(&chars, &mut pos)
}

