                i+=1;
                continue;
            }
        }
        if after_dd {
            if file_seen>=1 {
                let usage=build_usage(login_seen>0, norc_seen>0, c_seen>0, version_seen>0);
                print_error_unknown(arg, &usage);
                process::exit(1);
            } else {
                file_value=Some(arg.clone());
                file_seen+=1;
                i+=1;
                continue;
            }
        }
        if arg=="--" { after_dd=true; i+=1; continue; }
        if arg.starts_with("-c=") {
            c_seen+=1;
            if c_seen>1 {
                let usage=build_usage(login_seen>0, norc_seen>0, true, version_seen>0);
                print_error_duplicate("-c <command>", &usage);
                process::exit(1);
