                print_error_duplicate("-c <command>", &usage);
                process::exit(1);
            }
            command_value=Some(arg[2..].to_string());
            i+=1;
            continue;
        }
        match arg.as_str() {
            "-l" | "--login" => {
                login_seen+=1;
                if login_seen>1 {
                    let usage=build_usage(true, norc_seen>0, c_seen>0, version_seen>0);
                    print_error_duplicate("--login", &usage);
                    process::exit(1);
