    if let Some(file) = file_value {
        if command_value.is_none() {
            match fs::read_to_string(&file) {
                Ok(content) => {
                    // handle history? For file execution, does it write history? Earlier we saw history file remains empty for -c, but for file execution? Let's check file execution history.

