#[derive(Clone)]
struct Shell {
    vars: HashMap<String, String>,
    exported: HashMap<String, String>,
    aliases: HashMap<String, String>,
    last_exit: i32,
    set_e: bool,
    set_u: bool,
    set_n: bool,
    prev_dir: Option<String>,
}

impl Shell {
    fn new() -> Self {
        let mut vars = HashMap::new();
        let mut exported = HashMap::new();
        for (k,v) in env::vars() {
            vars.insert(k.clone(), v.clone());
            exported.insert(k, v);
        }
        let cwd = env::current_dir().unwrap_or_else(|_| Path::new("/").to_path_buf()).to_string_lossy().to_string();
        vars.entry("PWD".to_string()).or_insert(cwd);
        let shlvl = vars.get("SHLVL").cloned().unwrap_or("0".to_string());
        vars.insert("SHLVL".to_string(), shlvl.clone());
        exported.insert("SHLVL".to_string(), shlvl);
        if !vars.contains_key("HOME") {
            if let Some(home) = dirs::home_dir() {
                vars.insert("HOME".to_string(), home.to_string_lossy().to_string());
            }
