fn extract_for(s: &str) -> Option<(String, String)> {
    // Find matching done
    let mut depth=0;
    let mut i=0;
    let chars: Vec<char> = s.chars().collect();
    let mut in_single=false;
    let mut in_double=false;
    let mut last_done_end=0;
    let mut first_for_start=0;

    // We need to scan for keywords: for, while, if, case, done, fi, esac

    // For simplicity, we will look for "for" at beginning, then find "done" that balances

    // We'll token-scan via words

    // We'll create a simple state: we are looking for "done" that closes the initial for

    // We'll iterate through string, looking for keywords as separate words

    // We'll maintain a stack: when we see "for" or "while", push, when we see "done", pop, etc.

    // For our case, initial is "for", so stack = [for]

    // We'll search for keywords in order

    let mut stack: Vec<String> = Vec::new();
    stack.push("for".to_string());

    // We need to iterate over the string, finding keywords

    // We'll use a pointer and search for next keyword among for, while, if, case, done, fi, esac, do, etc.

    // For simplicity, we will split by whitespace and ; and newline into tokens, but keep positions

    // We'll create a function to find next keyword position

    let keywords = ["for", "while", "if", "case", "done", "fi", "esac"];

    let mut pos=0;
    // Skip initial "for"
    pos = s.find("for").unwrap_or(0) + 3;

    loop {
        // Find next keyword after pos
        let mut next: Option<(usize, String)> = None;
        let mut next_kw = "";
        for kw in keywords.iter() {
            if let Some(p) = s[pos..].find(kw) {
                let abs = pos + p;
                // Check word boundaries
                let before_ok = if abs==0 { true } else {
                    let bc = s[..abs].chars().last().unwrap_or(' ');
                    bc.is_whitespace() || bc==';' || bc=='\n'
                };
                let after_end = abs + kw.len();
                let after_ok = if after_end>=s.len() { true } else {
                    let ac = s[after_end..].chars().next().unwrap_or(' ');
                    ac.is_whitespace() || ac==';' || ac=='\n'
                };
                if before_ok && after_ok {
                    if next.is_none() || abs < next.unwrap().0 {
                        next = Some((abs, kw.to_string()));
                    }
                }
            }
        }
        if let Some((kw_pos, kw_str)) = next {
            if kw_str=="for" || kw_str=="while" {
                stack.push(kw_str);
                pos = kw_pos + kw_str.len();
            } else if kw_str=="if" || kw_str=="case" {
                stack.push(kw_str);
                pos = kw_pos + kw_str.len();
            } else if kw_str=="done" {
                // pop if top is for or while
                if let Some(top) = stack.last() {
                    if top=="for" || top=="while" {
                        stack.pop();
                        if stack.is_empty() {
                            // Found matching done for initial for
                            let end = kw_pos + kw_str.len();
                            let stmt = s[..end].to_string();
                            let rest = s[end..].to_string();
                            return Some((stmt, rest));
                        }
                    }
                }
                pos = kw_pos + kw_str.len();
            } else if kw_str=="fi" {
                if let Some(top) = stack.last() {
                    if top=="if" { stack.pop(); }
                }
                pos = kw_pos + kw_str.len();
            } else if kw_str=="esac" {
                if let Some(top) = stack.last() {
                    if top=="case" { stack.pop(); }
                }
                pos = kw_pos + kw_str.len();
            } else {
                pos = kw_pos + kw_str.len();
            }
        } else {
            break;
        }
    }
    None
}

