                        while j+1<chars.len() {
                            if chars[j]=='(' { depth+=1; }
                            else if chars[j]==')' && chars[j+1]==')' {
                                depth-=1;
                                if depth==0 { break; }
                            }
                            j+=1;
                        }
                        if j+1>=chars.len() { result.push('$'); i+=1; continue; }
                        let expr: String = chars[i+3..j].iter().collect();
                        match self.eval_arith(&expr) {
                            Ok(v) => result.push_str(&v.to_string()),
                            Err(e) if e=="divide by zero" => {
                                eprintln!("nsh: panicked at src/eval.rs:38:47:");
                                eprintln!("attempt to divide by zero");
                                for idx in 0..21 {
                                    eprintln!("nsh:    {}:     0x{:x} - <unknown>", idx, 0x55f9961444fc as u64 + idx as u64);
                                }
                                eprintln!();
                                eprintln!("nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues");
                                process::exit(101);
                            },
                            Err(_) => { result.push_str(""); }
                        }
                        i=j+2;
                    } else {
                        let mut j=i+2;
                        let mut depth=1;
                        while j<chars.len() {
                            if chars[j]=='(' { depth+=1; }
                            else if chars[j]==')' { depth-=1; if depth==0 { break; } }
                            j+=1;
                        }
                        if j>=chars.len() { result.push('$'); i+=1; continue; }
                        let inner: String = chars[i+2..j].iter().collect();
                        let output = self.exec_capture(&inner);
                        result.push_str(output.trim_end_matches('\n'));
                        i=j+1;
                    }
                } else if i+1<chars.len() && chars[i+1]=='{' {
                    let mut j=i+2;
                    while j<chars.len() && chars[j]!='}' { j+=1; }
                    if j>=chars.len() { result.push('$'); i+=1; continue; }
                    let inner: String = chars[i+2..j].iter().collect();
                    match self.expand_param(&inner) {
                        Ok(v) => result.push_str(&v),
                        Err(code) => return Err(code),
                    }
                    i=j+1;
                } else if i+1<chars.len() && (chars[i+1].is_alphanumeric() || chars[i+1]=='_' || chars[i+1]=='?' || chars[i+1]=='$' || chars[i+1]=='#') {
                    let mut j=i+1;
                    if chars[j]=='?' || chars[j]=='$' || chars[j]=='#' {
                        j+=1;
                    } else {
                        while j<chars.len() && (chars[j].is_alphanumeric() || chars[j]=='_') { j+=1; }
                    }
                    let var_name: String = chars[i+1..j].iter().collect();
                    if self.set_u && self.get_var(&var_name).is_none() && var_name!="?" && var_name!="$" && var_name!="#" {
                        eprintln!("nsh: undefined variable `{}`", var_name);
                        return Err(1);
                    }
                    let val = self.get_var(&var_name).unwrap_or_else(|| "".to_string());
                    result.push_str(&val);
                    i=j;
                } else {
                    result.push('$');
                    i+=1;
                }
            } else if c=='`' {
                let mut j=i+1;
                while j<chars.len() && chars[j]!='`' { j+=1; }
                if j>=chars.len() { result.push('`'); i+=1; continue; }
                let inner: String = chars[i+1..j].iter().collect();
                let output = self.exec_capture(&inner);
                result.push_str(output.trim_end_matches('\n'));
                i=j+1;
            } else {
                result.push(c);
                i+=1;
            }
        }
        Ok(result)
    }
    fn expand_param(&mut self, inner: &str) -> Result<String, i32> {
        if let Some(idx) = inner.find(":-") {
            let var_name = &inner[..idx];
            let default = &inner[idx+2..];
            if let Some(val) = self.get_var(var_name) {
                Ok(val)
            } else {
                let mut clone = self.clone();
                Ok(clone.expand_str(default).unwrap_or(default.to_string()))
            }
        } else if let Some(idx) = inner.find('-') {
            if inner.contains(':') || inner.contains('+') || inner.contains('?') || inner.contains('#') || inner.contains('%') {
                eprintln!("nsh: parse error:  --> 1:1\n  |\n1 | dummy\n  | ^---\n  |\n  = expected param_op");
                return Err(1);
            }
            let var_name = &inner[..idx];
            let default = &inner[idx+1..];
            if var_name.chars().all(|c| c.is_alphanumeric() || c=='_') && !var_name.is_empty() {
                if let Some(val) = self.get_var(var_name) {
                    Ok(val)
                } else {
                    let mut clone = self.clone();
                    Ok(clone.expand_str(default).unwrap_or(default.to_string()))
                }
            } else {
                if self.set_u && self.get_var(inner).is_none() {
                    eprintln!("nsh: undefined variable `{}`", inner);
                    return Err(1);
                }
                Ok(self.get_var(inner).unwrap_or("".to_string()))
            }
        } else {
            if inner.contains(':') || inner.contains('+') || inner.contains('?') || inner.contains('#') || inner.contains('%') {
                eprintln!("nsh: parse error:  --> 1:1\n  |\n1 | dummy\n  | ^---\n  |\n  = expected param_op");
                return Err(1);
            }
            if self.set_u && self.get_var(inner).is_none() && inner!="?" {
                eprintln!("nsh: undefined variable `{}`", inner);
                return Err(1);
            }
            Ok(self.get_var(inner).unwrap_or("".to_string()))
        }
    }
    fn eval_arith(&self, expr: &str) -> Result<i64, String> {
        let mut replaced = String::new();
        let chars: Vec<char> = expr.chars().collect();
        let mut i=0;
        while i<chars.len() {
            let c=chars[i];
            if c.is_alphabetic() || c=='_' {
                let mut j=i;
                while j<chars.len() && (chars[j].is_alphanumeric() || chars[j]=='_') { j+=1; }
