fn build_usage(login: bool, norc: bool, c_present: bool, version: bool) -> String {
    if !login && !norc && !c_present && !version { return "executable [FLAGS] [OPTIONS] [FILE]".to_string(); }
    let mut parts = vec!["executable".to_string()];
    if c_present { parts.push("-c <command>".to_string()); }
    if login { parts.push("--login".to_string()); }
    if norc { parts.push("--norc".to_string()); }
