fn split_next_command(s: &str) -> Option<(String, String, String)> {
    let mut in_single=false;
    let mut in_double=false;
    let chars: Vec<char> = s.chars().collect();
    let mut i=0;
    while i<chars.len() {
        let c=chars[i];
        if c=='\'' && !in_double { in_single=!in_single; }
        else if c=='"' && !in_single { in_double=!in_double; }
        if !in_single && !in_double {
            if c==';' {
                let cmd = s[..i].to_string();
                let rest = s[i+1..].to_string();
                return Some((cmd, ";".to_string(), rest));
            } else if c=='\n' {
                let cmd = s[..i].to_string();
                let rest = s[i+1..].to_string();
                return Some((cmd, "\n".to_string(), rest));
            } else if c=='&' {
                if i+1<chars.len() && chars[i+1]=='&' {
                    let cmd = s[..i].to_string();
                    let rest = s[i+2..].to_string();
                    return Some((cmd, "&&".to_string(), rest));
                } else {
                    if i>0 && chars[i-1]=='>' {
                        i+=1;
                        continue;
                    }
                    let cmd = s[..i].to_string();
                    let rest = s[i+1..].to_string();
                    return Some((cmd, "&".to_string(), rest));
                }
            } else if c=='|' {
                if i+1<chars.len() && chars[i+1]=='|' {
                    let cmd = s[..i].to_string();
                    let rest = s[i+2..].to_string();
                    return Some((cmd, "||".to_string(), rest));
                } else {
                    let cmd = s[..i].to_string();
                    let rest = s[i+1..].to_string();
                    return Some((cmd, "|".to_string(), rest));
                }
            }
        }
        i+=1;
    }
    None
}

fn find_chain_end(s: &str) -> Option<usize> {
    let mut in_single=false;
    let mut in_double=false;
    let chars: Vec<char> = s.chars().collect();
    let mut i=0;
    while i<chars.len() {
        let c=chars[i];
        if c=='\'' && !in_double { in_single=!in_single; }
        else if c=='"' && !in_single { in_double=!in_double; }
        if !in_single && !in_double {
            if c==';' || c=='\n' || c=='&' {
                if c=='&' && i+1<chars.len() && chars[i+1]=='&' {
                    i+=2;
                    continue;
                }
                return Some(i);
            }
        }
        i+=1;
    }
    None
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut has_help=false;
    let mut after_dd=false;
    for arg in args.iter().skip(1) {
        if after_dd { continue; }
        if arg=="--" { after_dd=true; continue; }
        if arg=="-h" || arg=="--help" { has_help=true; break; }
    }
    if has_help { print_help(); process::exit(0); }

    let mut login_seen=0;
    let mut norc_seen=0;
    let mut c_seen=0;
    let mut version_seen=0;
    let mut file_seen=0;
    let mut command_value: Option<String>=None;
    let mut file_value: Option<String>=None;
    let mut pending_c=false;
    after_dd=false;
    let mut i=1;
    while i<args.len() {
        let arg=&args[i];
        if pending_c {
            let is_flag = matches!(arg.as_str(), "-h" | "--help" | "-l" | "--login" | "--norc" | "--version" | "-c");
            if is_flag || (arg.starts_with("-") && arg!="-") {
