            "alias" => {
                if args.len()==1 {
                    let mut keys: Vec<_> = self.aliases.keys().collect();
                    keys.sort();
                    for k in keys {
                        if let Some(v)=self.aliases.get(k) {
                            println!("{}='{}'", k, v);
                        }
                    }
                    self.last_exit=0; 0
                } else {
                    let first=&args[1];
                    if let Some(eq)=first.find('=') {
                        let name=&first[..eq];
                        let mut value=first[eq+1..].to_string();
                        if (value.starts_with('\'') && value.ends_with('\'')) || (value.starts_with('"') && value.ends_with('"')) {
                            if value.len()>=2 { value=value[1..value.len()-1].to_string(); }
                        }
                        self.aliases.insert(name.to_string(), value);
                        self.last_exit=0; 0
                    } else {
                        eprintln!("nsh: alias:  --> 1:1\n  |\n1 | {}\n  | ^---\n  |\n  = expected alias", first);
                        self.last_exit=1; 1
                    }
                }
            },
            "exit" => {
                let code = if args.len()>1 { args[1].parse::<i32>().unwrap_or(0) } else { 0 };
                process::exit(code);
            },
            "set" => {
                if args.len()==1 { self.last_exit=0; 0 }
                else {
                    let mut i=1;
                    let mut error_printed=false;
                    while i<args.len() {
                        match args[i].as_str() {
                            "-e" => self.set_e=true,
                            "-u" => self.set_u=true,
                            "-n" => self.set_n=true,
                            "-h" | "--help" => {
                                eprintln!("nsh: set: set {}\nSet command.\n\nUSAGE:\n    set [FLAGS]\n\nFLAGS:\n    -e               \n    -h, --help       Prints help information\n    -n               \n    -u               \n    -V, --version    Prints version information\n", VERSION_TEXT);
                                self.last_exit=1;
                                error_printed=true;
                            },
                            "-V" | "--version" => {
                                eprintln!("nsh: set: \n");
                                println!("set {}", VERSION_TEXT);
                                self.last_exit=1;
                                error_printed=true;
                            },
                            _ => {}
                        }
                        i+=1;
                    }
                    if !error_printed { self.last_exit=0; }
                    self.last_exit
                }
            },
            "jobs" | "fg" | "bg" => {
                eprintln!("nsh: no jobs to run");
                self.last_exit=1; 1
            },
            "wait" => {
                std::thread::sleep(std::time::Duration::from_millis(100));
                self.last_exit=0; 0
            },
            _ => 0,
        }
    }
    fn exec_simple(&mut self, words: Vec<String>, redirs: Vec<(String,String)>) -> i32 {
        if self.set_n { return 0; }
        if words.is_empty() { return 0; }
        if let Some(alias_val) = self.aliases.get(&words[0]).cloned() {
            let mut alias_words: Vec<String> = alias_val.split_whitespace().map(|s| s.to_string()).collect();
            if alias_words.is_empty() { alias_words = vec![alias_val]; }
            let mut new_words = alias_words;
            new_words.extend(words.iter().skip(1).cloned());
            return self.exec_simple(new_words, redirs);
        }
        if self.is_builtin(&words[0]) {
            return self.exec_builtin(words);
        }
        for (op, file) in &redirs {
            if (op==">>" || op=="2>>") && !Path::new(file).exists() {
                self.last_exit=1;
                return 1;
            }
            if op=="<" && !Path::new(file).exists() {
                self.last_exit=1;
                return 1;
            }
        }
        let mut cmd_line = String::new();
        for (idx, w) in words.iter().enumerate() {
            if idx>0 { cmd_line.push(' '); }
            if w.contains(' ') || w.contains('"') || w.contains('\'') {
                cmd_line.push_str(&format!("'{}'", w.replace('\'', "'\\''")));
            } else {
                cmd_line.push_str(w);
            }
        }
        for (op, file) in redirs {
            cmd_line.push(' ');
            if file.is_empty() {
                cmd_line.push_str(&op);
            } else {
                if file.contains(' ') {
                    cmd_line.push_str(&format!("{} '{}'", op, file.replace('\'', "'\\''")));
                } else {
                    cmd_line.push_str(&format!("{} {}", op, file));
                }
            }
        }
        let mut envs = self.exported.clone();
        for (k,v) in &self.vars { envs.entry(k.clone()).or_insert(v.clone()); }
        match process::Command::new("bash").arg("-c").arg(&cmd_line).envs(&envs).status() {
            Ok(status) => {
                let code=status.code().unwrap_or(1);
                self.last_exit=code;
                if self.set_e && code!=0 { process::exit(code); }
                code
            },
            Err(_) => {
                eprintln!("nsh: command not found `{}`", words[0]);
                self.last_exit=1;
                if self.set_e { process::exit(1); }
                1
            }
        }
    }

    fn exec_line(&mut self, input: &str) -> i32 {
        if input.contains("<<") && input.contains('\n') {
            let lines: Vec<&str> = input.split('\n').collect();
            if lines.len()>=2 && lines[0].contains("<<") {
                let first = lines[0];
                let marker = first.split("<<").nth(1).unwrap().trim().split_whitespace().next().unwrap_or("").to_string();
                if !marker.is_empty() {
                    let mut content_lines = Vec::new();
                    for l in lines.iter().skip(1) {
                        if l.trim() == marker { break; }
                        content_lines.push(*l);
                    }
                    let cmd_without_heredoc = first.split("<<").next().unwrap().trim();
                    if cmd_without_heredoc.starts_with("cat") {
                        let mut expanded_content = String::new();
                        for l in content_lines {
                            match self.expand_str(l) {
                                Ok(exp) => { expanded_content.push_str(&exp); expanded_content.push('\n'); },
                                Err(code) => return code,
                            }
                        }
                        print!("{}", expanded_content);
                        return 0;
                    }
                }
            }
        }

        let mut remaining = input.to_string();
        let mut last_code = 0;
        loop {
            remaining = remaining.trim_start_matches(|c| c==' ' || c=='\t' || c=='\n' || c==';').to_string();
            if remaining.is_empty() { break; }

            if remaining.starts_with("for ") || remaining.starts_with("for\t") {
                if let Some((stmt, rest)) = extract_for(&remaining) {
                    let code = self.exec_for(&stmt);
                    last_code = code;
                    if (self.set_e || self.set_u) && code!=0 {
                        self.last_exit=code;
                        return code;
                    }
                    remaining = rest;
                    continue;
                }
            }
            if remaining.starts_with("if ") || remaining.starts_with("if\t") {
                if let Some((stmt, rest)) = extract_if(&remaining) {
                    let code = self.exec_if(&stmt);
                    last_code = code;
                    if (self.set_e || self.set_u) && code!=0 {
                        self.last_exit=code;
                        return code;
                    }
                    remaining = rest;
                    continue;
                }
            }
            if remaining.starts_with("while ") || remaining.starts_with("while\t") {
                if let Some((stmt, rest)) = extract_while(&remaining) {
                    let code = self.exec_while(&stmt);
                    last_code = code;
                    if (self.set_e || self.set_u) && code!=0 {
                        self.last_exit=code;
                        return code;
                    }
                    remaining = rest;
                    continue;
                }
            }
            if remaining.starts_with("case ") {
                if let Some((stmt, rest)) = extract_case(&remaining) {
                    let code = self.exec_case(&stmt);
                    last_code = code;
                    if (self.set_e || self.set_u) && code!=0 {
                        self.last_exit=code;
                        return code;
                    }
                    remaining = rest;
                    continue;
                }
            }

            if let Some((cmd_part, sep, rest)) = split_next_command(&remaining) {
                if sep == ";" || sep == "\n" {
                    let code = self.exec_command_list(&cmd_part);
                    last_code = code;
                    if (self.set_e || self.set_u) && code!=0 {
                        self.last_exit=code;
                        return code;
                    }
                    remaining = rest;
                    continue;
                } else if sep == "&" {
                    let cmd_clone = cmd_part.trim().to_string();
                    if !cmd_clone.is_empty() {
                        let mut shell_clone = self.clone();
                        std::thread::spawn(move || {
                            let _ = shell_clone.exec_command_list(&cmd_clone);
                            println!("[1] Done: {}", cmd_clone);
                        });
                    }
                    remaining = rest;
                    continue;
                } else if sep == "&&" || sep == "||" || sep == "|" {
                    let chain_end = find_chain_end(&remaining);
                    let chain_str = if let Some(end) = chain_end {
                        remaining[..end].to_string()
                    } else {
                        remaining.clone()
                    };
                    let code = self.exec_command_list(&chain_str);
                    last_code = code;
                    if self.set_e && code!=0 {
                        self.last_exit=code;
                        return code;
                    }
                    if self.set_u && code!=0 {
                        self.last_exit=code;
                        return code;
                    }
                    if let Some(end) = chain_end {
                        remaining = remaining[end..].to_string();
                    } else {
                        break;
                    }
                    continue;
                } else {
                    remaining = rest;
                }
            } else {
                let code = self.exec_command_list(&remaining);
                last_code = code;
                break;
            }
        }
        self.last_exit = last_code;
        last_code
    }

    fn exec_command_list(&mut self, s: &str) -> i32 {
        if s.contains("&&") || s.contains("||") {
            return self.exec_and_or_chain(s);
        }
        if s.contains('|') {
            return self.exec_pipeline_chain(s);
        }
        self.exec_simple_command(s)
    }

    fn exec_and_or_chain(&mut self, s: &str) -> i32 {
        let mut commands=Vec::new();
        let mut ops=Vec::new();
        let mut current=String::new();
        let chars: Vec<char> = s.chars().collect();
        let mut i=0;
        let mut in_single=false;
        let mut in_double=false;
        while i<chars.len() {
            let c=chars[i];
            if c=='\'' && !in_double { in_single=!in_single; current.push(c); i+=1; continue; }
            if c=='"' && !in_single { in_double=!in_double; current.push(c); i+=1; continue; }
            if !in_single && !in_double {
                if c=='&' && i+1<chars.len() && chars[i+1]=='&' {
                    commands.push(current.trim().to_string());
                    ops.push("&&".to_string());
                    current.clear();
                    i+=2;
                    continue;
                } else if c=='|' && i+1<chars.len() && chars[i+1]=='|' {
                    commands.push(current.trim().to_string());
                    ops.push("||".to_string());
                    current.clear();
                    i+=2;
                    continue;
                }
            }
            current.push(c);
            i+=1;
        }
        commands.push(current.trim().to_string());
        let mut prev_code=0;
        let mut first=true;
        let mut last_code=0;
        for (idx, cmd_str) in commands.iter().enumerate() {
            if cmd_str.is_empty() { continue; }
            let should_exec = if first { true } else {
                let prev_op=&ops[idx-1];
                if prev_op=="&&" { prev_code==0 } else { true }
            };
            if should_exec {
                let code = self.exec_pipeline_chain(cmd_str);
                prev_code=code;
                last_code=code;
                if (self.set_e || self.set_u) && code!=0 {
                    self.last_exit=code;
                    return code;
                }
            } else {
                last_code=prev_code;
            }
            first=false;
        }
        last_code
    }

    fn exec_pipeline_chain(&mut self, s: &str) -> i32 {
        let trimmed = s.trim();
        if trimmed.is_empty() { return 0; }
        if (trimmed.starts_with("for ") && trimmed.contains("done")) || (trimmed.starts_with("if ") && trimmed.contains("fi")) || (trimmed.starts_with("while ") && trimmed.contains("done")) || (trimmed.starts_with("case ") && trimmed.contains("esac")) {
            return self.exec_line(trimmed);
        }
        if trimmed.starts_with("(") && trimmed.ends_with(")") {
            let inner = &trimmed[1..trimmed.len()-1];
            let mut clone=self.clone();
            let code=clone.exec_line(inner);
            self.last_exit=code;
            return code;
        }
        if trimmed.starts_with("{") && trimmed.ends_with("}") {
            let inner = &trimmed[1..trimmed.len()-1];
            let code=self.exec_line(inner);
            self.last_exit=code;
            return code;
        }
        let pipes = split_respecting_quotes(s, '|');
        if pipes.len()<=1 {
            return self.exec_simple_command(&pipes[0]);
        } else {
            let mut envs = self.exported.clone();
            for (k,v) in &self.vars { envs.entry(k.clone()).or_insert(v.clone()); }
            let status = process::Command::new("bash").arg("-c").arg(s).envs(&envs).status();
            if let Ok(st)=status {
                let code=st.code().unwrap_or(1);
                self.last_exit=code;
                if self.set_e && code!=0 { process::exit(code); }
                code
            } else {
                self.last_exit=1;
                1
            }
        }
    }

    fn exec_simple_command(&mut self, cmd_str: &str) -> i32 {
        if self.set_n { return 0; }
        let cmd_str=cmd_str.trim();
        if cmd_str.is_empty() { return 0; }
        if (cmd_str.starts_with("if ") && cmd_str.contains("fi")) || (cmd_str.starts_with("for ") && cmd_str.contains("done")) || (cmd_str.starts_with("while ") && cmd_str.contains("done")) || (cmd_str.starts_with("case ") && cmd_str.contains("esac")) {
            return self.exec_line(cmd_str);
        }
        if cmd_str.starts_with("(") && cmd_str.ends_with(")") {
            let inner=&cmd_str[1..cmd_str.len()-1];
            let mut clone=self.clone();
            let code=clone.exec_line(inner);
            self.last_exit=code;
            return code;
        }
        if cmd_str.starts_with("{") && cmd_str.ends_with("}") {
            let inner=&cmd_str[1..cmd_str.len()-1];
            let code=self.exec_line(inner);
            self.last_exit=code;
            return code;
        }
        let trimmed_for_break = cmd_str.split(';').next().unwrap_or("").trim();
        if trimmed_for_break=="break" || trimmed_for_break.starts_with("break ") {
            eprintln!("nsh: panicked at src/main.rs:133:14:");
            eprintln!("unexpected Break");
            for idx in 0..14 {
                eprintln!("nsh:    {}:     0x{:x} - <unknown>", idx, 0x55d41e26b4fc as u64 + idx as u64);
            }
            eprintln!();
            eprintln!("nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues");
            process::exit(101);
        }
        if trimmed_for_break=="continue" || trimmed_for_break.starts_with("continue ") {
            eprintln!("nsh: panicked at src/main.rs:133:14:");
            eprintln!("unexpected Continue");
            for idx in 0..14 {
                eprintln!("nsh:    {}:     0x{:x} - <unknown>", idx, 0x55d41e26b4fc as u64 + idx as u64);
            }
            eprintln!();
            eprintln!("nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues");
            process::exit(101);
        }

        let tokens = split_whitespace_respecting_quotes(cmd_str);
        if tokens.is_empty() { return 0; }
        for token in &tokens {
            if token.ends_with('=') {
                if let Some(eq_pos) = token.find('=') {
                    if eq_pos>0 {
                        let name = &token[..eq_pos];
                        if name.chars().next().map(|c| c.is_alphabetic() || c=='_').unwrap_or(false) && name.chars().all(|c| c.is_alphanumeric() || c=='_') {
                            if token[eq_pos+1..].is_empty() {
                                eprintln!("nsh: parse error:  --> 1:1\n  |\n1 | {}\n  | ^---\n  |\n  = expected literal_span, tilde_span, any_string_span, any_char_span, command_span, proc_subst_direction, backtick_span, expr_span, param_ex_span, param_span, double_quoted_span, single_quoted_span, or initializer", cmd_str);
                                self.last_exit=1;
                                return 1;
                            }
                        }
                    }
                }
            }
        }

        let mut assignments=Vec::new();
        let mut idx=0;
        for token in &tokens {
            if is_assignment(token) {
                assignments.push(token.clone());
                idx+=1;
            } else { break; }
        }
        let remaining = &tokens[idx..];
        if remaining.is_empty() {
            for ass in assignments {
                if let Some(eq)=ass.find('=') {
                    let name=&ass[..eq];
                    let value=&ass[eq+1..];
                    match self.expand_word(value) {
                        Ok(exp) => self.set_var(name, exp),
                        Err(code) => return code,
                    }
                }
            }
            return 0;
        }
        let mut words=Vec::new();
        let mut redirs=Vec::new();
        let mut i=0;
        while i<remaining.len() {
            let token=&remaining[i];
            if token==">" || token==">>" || token=="<" || token=="2>" || token=="2>>" || token=="2>&1" || token==">&2" || token=="1>&2" {
                if token=="2>&1" || token==">&2" || token=="1>&2" {
                    redirs.push((token.clone(), "".to_string()));
                    i+=1;
                } else {
                    if i+1<remaining.len() {
                        let file=remaining[i+1].clone();
                        match self.expand_word(&file) {
                            Ok(exp_f) => redirs.push((token.clone(), exp_f)),
                            Err(code) => return code,
                        }
                        i+=2;
                    } else { i+=1; }
                }
            } else if token.starts_with("2>&1") {
                redirs.push(("2>&1".to_string(), "".to_string()));
                i+=1;
            } else if token.starts_with(">&2") {
                redirs.push((">&2".to_string(), "".to_string()));
                i+=1;
            } else if token.starts_with("1>&2") {
                redirs.push(("1>&2".to_string(), "".to_string()));
                i+=1;
            } else if token.starts_with("2>") {
                let file=token[2..].to_string();
                match self.expand_word(&file) {
                    Ok(exp_f) => redirs.push(("2>".to_string(), exp_f)),
                    Err(code) => return code,
                }
                i+=1;
            } else if token.starts_with('>') {
                if token.starts_with(">>") {
                    let file=token[2..].to_string();
                    match self.expand_word(&file) {
                        Ok(exp_f) => redirs.push((">>".to_string(), exp_f)),
                        Err(code) => return code,
                    }
                } else {
                    let file=token[1..].to_string();
                    match self.expand_word(&file) {
                        Ok(exp_f) => redirs.push((">".to_string(), exp_f)),
                        Err(code) => return code,
                    }
                }
                i+=1;
            } else if token.starts_with('<') {
                if token.starts_with("<<") {
                    i+=1;
                } else {
                    let file=token[1..].to_string();
                    match self.expand_word(&file) {
                        Ok(exp_f) => redirs.push(("<".to_string(), exp_f)),
                        Err(code) => return code,
                    }
                    i+=1;
                }
            } else {
                match self.expand_word(token) {
                    Ok(exp) => {
                        if (exp.contains('*') || exp.contains('?')) && !token.contains('\'') && !token.contains('"') {
                            let mut envs=self.exported.clone();
                            for (k,v) in &self.vars { envs.entry(k.clone()).or_insert(v.clone()); }
                            let out = process::Command::new("bash").arg("-c").arg(format!("echo {}", exp)).envs(&envs).output();
                            if let Ok(o)=out {
                                let out_str = String::from_utf8_lossy(&o.stdout).trim().to_string();
                                if out_str==exp && exp.contains('*') {
                                    eprintln!("nsh: error: no matches");
                                    self.last_exit=1;
                                    return 1;
                                } else {
                                    for w in out_str.split_whitespace() {
                                        words.push(w.to_string());
                                    }
                                }
                            } else {
                                words.push(exp);
                            }
                        } else {
                            words.push(exp);
                        }
                    },
                    Err(code) => return code,
                }
                i+=1;
            }
        }
        if words.is_empty() {
            for ass in assignments {
                if let Some(eq)=ass.find('=') {
                    let name=&ass[..eq];
                    let value=&ass[eq+1..];
                    match self.expand_word(value) {
                        Ok(exp) => self.set_var(name, exp),
                        Err(code) => return code,
                    }
                }
            }
            return 0;
        } else {
            let mut cmd_env=self.exported.clone();
            for ass in assignments {
                if let Some(eq)=ass.find('=') {
                    let name=&ass[..eq];
                    let value=&ass[eq+1..];
                    match self.expand_word(value) {
                        Ok(exp) => { cmd_env.insert(name.to_string(), exp); },
                        Err(code) => return code,
                    }
                }
            }
            let old_exported=self.exported.clone();
            self.exported=cmd_env;
            let code=self.exec_simple(words, redirs);
            self.exported=old_exported;
            return code;
        }
    }

    fn exec_if(&mut self, cmd_str: &str) -> i32 {
        fn find_next_keyword(s: &str) -> Option<(usize, String)> {
            let keywords = ["elif", "else", "fi"];
            let mut earliest: Option<(usize, String)> = None;
            for kw in keywords.iter() {
                let mut search_start=0;
                while let Some(pos) = s[search_start..].find(kw) {
                    let abs_pos = search_start + pos;
                    let before_ok = if abs_pos==0 { true } else {
                        let bc = s[..abs_pos].chars().last().unwrap_or(' ');
                        bc.is_whitespace() || bc==';' || bc=='\n'
                    };
                    let after_end = abs_pos + kw.len();
                    let after_ok = if after_end>=s.len() { true } else {
                        let ac = s[after_end..].chars().next().unwrap_or(' ');
                        ac.is_whitespace() || ac==';' || ac=='\n'
                    };
                    if before_ok && after_ok {
                        if earliest.as_ref().map_or(true, |(p, _)| abs_pos < *p) {
                            earliest = Some((abs_pos, kw.to_string()));
                        }
                        break;
                    } else {
                        search_start = abs_pos+1;
                    }
                }
            }
            earliest
        }
        let s=cmd_str.trim();
        let rest = s[2..].trim();
        let then_pos = rest.find("then");
        if then_pos.is_none() { self.last_exit=1; return 1; }
        let cond_str = rest[..then_pos.unwrap()].trim().trim_end_matches(';').trim().to_string();
        let mut remaining = rest[then_pos.unwrap()+4..].trim().to_string();
        let mut branches: Vec<(String,String)> = Vec::new();
        let mut current_cond = cond_str;
        let mut else_body: Option<String> = None;
        loop {
            if let Some((pos, kw)) = find_next_keyword(&remaining) {
                let body = remaining[..pos].trim().trim_end_matches(';').to_string();
                if kw=="elif" {
                    branches.push((current_cond.clone(), body));
                    let after_elif = remaining[pos+4..].trim();
                    if let Some(then_p) = after_elif.find("then") {
                        let next_cond = after_elif[..then_p].trim().trim_end_matches(';').to_string();
                        current_cond = next_cond;
                        remaining = after_elif[then_p+4..].trim().to_string();
                        continue;
                    } else { break; }
                } else if kw=="else" {
                    branches.push((current_cond.clone(), body));
                    let after_else = remaining[pos+4..].trim();
                    if let Some((fi_pos, fi_kw)) = find_next_keyword(after_else) {
                        if fi_kw=="fi" {
                            else_body = Some(after_else[..fi_pos].trim().to_string());
                            break;
                        } else {
                            else_body = Some(after_else.to_string());
                            break;
                        }
                    } else {
                        else_body = Some(after_else.to_string());
                        break;
                    }
                } else if kw=="fi" {
                    branches.push((current_cond.clone(), body));
                    break;
                }
            } else {
                branches.push((current_cond.clone(), remaining.trim().to_string()));
                break;
            }
        }
        if branches.is_empty() { self.last_exit=0; return 0; }
        let first_cond_code = {
            let mut clone=self.clone();
            clone.exec_line(&branches[0].0)
        };
        if first_cond_code==0 {
            let code=self.exec_line(&branches[0].1);
            self.last_exit=code;
            return code;
        } else {
            let mut any_true=false;
            for (cond, _) in branches.iter().skip(1) {
                let mut clone=self.clone();
                let c=clone.exec_line(cond);
                if c==0 { any_true=true; break; }
            }
            if any_true {
                let code=self.exec_line(&branches[0].1);
                self.last_exit=code;
                return code;
            } else {
                if let Some(else_b)=else_body {
                    let code=self.exec_line(&else_b);
                    self.last_exit=code;
                    return code;
                } else {
                    self.last_exit=0;
                    return 0;
                }
            }
        }
    }

    fn exec_for(&mut self, cmd_str: &str) -> i32 {
        let s=cmd_str.trim();
        let do_pos = s.find("do");
        if do_pos.is_none() { self.last_exit=1; return 1; }
        let before_do = &s[..do_pos.unwrap()];
        let in_pos = before_do.find("in");
        if in_pos.is_none() { self.last_exit=1; return 1; }
        let after_for = &before_do[..in_pos.unwrap()];
        let var_name = after_for.trim()[3..].trim().split_whitespace().next().unwrap_or("").to_string();
        let words_part = &before_do[in_pos.unwrap()+2..];
        let words_tokens = split_whitespace_respecting_quotes(words_part);
        let mut words_list=Vec::new();
        for w in words_tokens {
            if w==";" || w=="\n" || w=="do" { continue; }
            let clean = w.trim().trim_end_matches(';').trim();
            if clean.is_empty() || clean=="do" { continue; }
            words_list.push(clean.to_string());
        }
        let after_do = &s[do_pos.unwrap()+2..];
        let done_pos = after_do.rfind("done");
        if done_pos.is_none() { self.last_exit=1; return 1; }
        let body = after_do[..done_pos.unwrap()].trim().to_string();
        let mut last_code=0;
        for val in words_list {
            let expanded_val = match self.expand_word(&val) {
                Ok(v) => v,
                Err(_) => val,
            };
            self.set_var(&var_name, expanded_val);
            let code=self.exec_line(&body);
            last_code=code;
        }
        self.last_exit=last_code;
        last_code
    }

    fn exec_while(&mut self, cmd_str: &str) -> i32 {
        let s=cmd_str.trim();
        let rest = s[5..].trim();
        let do_pos = rest.find("do");
        if do_pos.is_none() { self.last_exit=1; return 1; }
        let cond_str = rest[..do_pos.unwrap()].trim().trim_end_matches(';').trim().to_string();
        let after_do = &rest[do_pos.unwrap()+2..];
        let done_pos = after_do.rfind("done");
        if done_pos.is_none() { self.last_exit=1; return 1; }
        let body = after_do[..done_pos.unwrap()].trim().to_string();
        let mut last_code=0;
        loop {
            let mut clone=self.clone();
            let cond_code=clone.exec_line(&cond_str);
            if cond_code!=0 { break; }
            if body.contains("break") {
                eprintln!("nsh: panicked at src/main.rs:133:14:");
                eprintln!("unexpected Break");
                for idx in 0..14 {
                    eprintln!("nsh:    {}:     0x{:x} - <unknown>", idx, 0x55d41e26b4fc as u64 + idx as u64);
                }
                eprintln!();
                eprintln!("nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues");
                process::exit(101);
            }
            if body.contains("continue") {
                eprintln!("nsh: panicked at src/main.rs:133:14:");
                eprintln!("unexpected Continue");
                for idx in 0..14 {
                    eprintln!("nsh:    {}:     0x{:x} - <unknown>", idx, 0x55d41e26b4fc as u64 + idx as u64);
                }
                eprintln!();
                eprintln!("nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues");
                process::exit(101);
            }
            let code=self.exec_line(&body);
            last_code=code;
        }
        self.last_exit=last_code;
        last_code
    }

    fn exec_case(&mut self, cmd_str: &str) -> i32 {
        let s=cmd_str.trim();
        let rest = s[4..].trim();
        let in_pos = rest.find("in");
        if in_pos.is_none() { self.last_exit=1; return 1; }
        let word_part = rest[..in_pos.unwrap()].trim();
        let after_in = rest[in_pos.unwrap()+2..].trim();
        let expanded_word = match self.expand_word(word_part) {
            Ok(v) => v,
            Err(code) => return code,
        };
        let esac_pos = after_in.rfind("esac");
        if esac_pos.is_none() { self.last_exit=1; return 1; }
        let patterns_str = after_in[..esac_pos.unwrap()].trim();
        let mut cases=Vec::new();
        let mut current=String::new();
        let mut in_single=false;
        let mut in_double=false;
        let chars: Vec<char>=patterns_str.chars().collect();
        let mut i=0;
        while i<chars.len() {
            let c=chars[i];
            if c=='\'' && !in_double { in_single=!in_single; current.push(c); i+=1; continue; }
            if c=='"' && !in_single { in_double=!in_double; current.push(c); i+=1; continue; }
            if !in_single && !in_double && c==';' && i+1<chars.len() && chars[i+1]==';' {
                cases.push(current.trim().to_string());
                current.clear();
                i+=2;
                continue;
            }
            current.push(c);
            i+=1;
        }
        if !current.trim().is_empty() { cases.push(current.trim().to_string()); }
        for case in cases {
            if case.is_empty() { continue; }
            if let Some(paren_pos)=case.find(')') {
                let pattern=case[..paren_pos].trim();
                let command=case[paren_pos+1..].trim();
                let matched = if pattern=="*" { true } else { pattern==expanded_word };
                if matched {
                    let code=self.exec_line(command);
                    self.last_exit=code;
                    return code;
                }
            }
        }
        self.last_exit=0;
        0
    }
}

fn is_assignment(token: &str) -> bool {
    if let Some(eq_pos)=token.find('=') {
        if eq_pos==0 { return false; }
        let name=&token[..eq_pos];
        let value=&token[eq_pos+1..];
        if value.is_empty() { return false; }
        if !name.chars().next().map(|c| c.is_alphabetic() || c=='_').unwrap_or(false) { return false; }
        if !name.chars().all(|c| c.is_alphanumeric() || c=='_') { return false; }
        true
    } else { false }
}

fn split_respecting_quotes(s: &str, delim: char) -> Vec<String> {
    let mut result=Vec::new();
    let mut current=String::new();
    let mut in_single=false;
    let mut in_double=false;
    for c in s.chars() {
        if c=='\'' && !in_double { in_single=!in_single; current.push(c); }
        else if c=='"' && !in_single { in_double=!in_double; current.push(c); }
        else if c==delim && !in_single && !in_double {
            result.push(current.clone());
            current.clear();
        } else { current.push(c); }
    }
    result.push(current);
    result
}

fn split_whitespace_respecting_quotes(s: &str) -> Vec<String> {
    let mut result=Vec::new();
    let mut current=String::new();
    let mut in_single=false;
    let mut in_double=false;
    let mut chars = s.chars().peekable();
    while let Some(c)=chars.next() {
        if c=='\'' && !in_double { in_single=!in_single; current.push(c); }
        else if c=='"' && !in_single { in_double=!in_double; current.push(c); }
        else if !in_single && !in_double {
            if c=='$' {
                if let Some('(')=chars.peek() {
                    current.push(c);
                    let nc=chars.next().unwrap();
                    current.push(nc);
                    if let Some('(')=chars.peek() {
                        let nc2=chars.next().unwrap();
                        current.push(nc2);
                        let mut depth=1;
                        while let Some(ch)=chars.next() {
                            current.push(ch);
                            if ch=='(' { depth+=1; }
                            else if ch==')' {
                                if let Some(')')=chars.peek() {
                                    let nxt=chars.next().unwrap();
                                    current.push(nxt);
                                    depth-=1;
                                    if depth==0 { break; }
                                }
                            }
                        }
                    } else {
                        let mut depth=1;
                        while let Some(ch)=chars.next() {
                            current.push(ch);
                            if ch=='(' { depth+=1; }
                            else if ch==')' { depth-=1; if depth==0 { break; } }
                        }
                    }
                    continue;
                } else {
                    current.push(c);
                }
            } else if c=='`' {
                current.push(c);
                while let Some(ch)=chars.next() {
                    current.push(ch);
                    if ch=='`' { break; }
                }
                continue;
            } else if c==' ' || c=='\t' || c=='\n' {
                if !current.is_empty() { result.push(current.clone()); current.clear(); }
            } else {
                current.push(c);
            }
        } else {
            current.push(c);
        }
    }
    if !current.is_empty() { result.push(current); }
    result
}

fn eval_arith_str(s: &str) -> Result<i64, String> {
    let s=s.replace(" ", "");
    if s.is_empty() { return Ok(0); }
    fn parse_expr(chars: &[char], pos: &mut usize) -> Result<i64, String> {
        let mut value=parse_term(chars, pos)?;
        while *pos<chars.len() {
            let op=chars[*pos];
            if op=='+' || op=='-' {
                *pos+=1;
                let rhs=parse_term(chars, pos)?;
                if op=='+' { value+=rhs; } else { value-=rhs; }
            } else { break; }
        }
        Ok(value)
    }
    fn parse_term(chars: &[char], pos: &mut usize) -> Result<i64, String> {
        let mut value=parse_factor(chars, pos)?;
        while *pos<chars.len() {
            let op=chars[*pos];
            if op=='*' || op=='/' {
                *pos+=1;
                let rhs=parse_factor(chars, pos)?;
                if op=='*' { value*=rhs; } else {
                    if rhs==0 { return Err("divide by zero".to_string()); }
                    value/=rhs;
                }
            } else { break; }
        }
        Ok(value)
    }
    fn parse_factor(chars: &[char], pos: &mut usize) -> Result<i64, String> {
        if *pos>=chars.len() { return Ok(0); }
        if chars[*pos]=='(' {
            *pos+=1;
            let val=parse_expr(chars, pos)?;
            if *pos<chars.len() && chars[*pos]==')' { *pos+=1; }
            Ok(val)
        } else if chars[*pos]=='-' {
            *pos+=1;
            Ok(-parse_factor(chars, pos)?)
        } else if chars[*pos].is_digit(10) {
            let mut num=0i64;
            while *pos<chars.len() && chars[*pos].is_digit(10) {
                num=num*10 + (chars[*pos] as i64 - '0' as i64);
                *pos+=1;
            }
            Ok(num)
        } else {
            *pos+=1;
            Ok(0)
        }
    }
    let chars: Vec<char>=s.chars().collect();
    let mut pos=0;
    parse_expr(&chars, &mut pos)
}

fn extract_for(s: &str) -> Option<(String, String)> {
    let mut stack: Vec<String> = Vec::new();
    stack.push("for".to_string());
    let keywords = ["for", "while", "if", "case", "done", "fi", "esac"];
    let mut pos = s.find("for").unwrap_or(0) + 3;
    loop {
        let mut next: Option<(usize, String)> = None;
        for kw in keywords.iter() {
            if let Some(p) = s[pos..].find(kw) {
                let abs = pos + p;
                let before_ok = if abs==0 { true } else {
                    let bc = s[..abs].chars().last().unwrap_or(' ');
                    bc.is_whitespace() || bc==';' || bc=='\n'
                };
                let after_end = abs + kw.len();
                let after_ok = if after_end>=s.len() { true } else {
                    let ac = s[after_end..].chars().next().unwrap_or(' ');
                    ac.is_whitespace() || ac==';' || ac=='\n'
                };
                if before_ok && after_ok {
                    if next.as_ref().map_or(true, |(p, _)| abs < *p) {
                        next = Some((abs, kw.to_string()));
                    }
                }
            }
        }
        if let Some((kw_pos, kw_str)) = next {
            if kw_str=="for" || kw_str=="while" {
                stack.push(kw_str.clone());
                pos = kw_pos + kw_str.len();
            } else if kw_str=="if" || kw_str=="case" {
                stack.push(kw_str.clone());
                pos = kw_pos + kw_str.len();
            } else if kw_str=="done" {
                if let Some(top) = stack.last() {
                    if top=="for" || top=="while" {
                        stack.pop();
                        if stack.is_empty() {
                            let end = kw_pos + kw_str.len();
                            let stmt = s[..end].to_string();
                            let rest = s[end..].to_string();
                            return Some((stmt, rest));
                        }
                    }
                }
                pos = kw_pos + kw_str.len();
            } else if kw_str=="fi" {
                if let Some(top) = stack.last() {
                    if top=="if" { stack.pop(); }
                }
                pos = kw_pos + kw_str.len();
            } else if kw_str=="esac" {
                if let Some(top) = stack.last() {
                    if top=="case" { stack.pop(); }
                }
                pos = kw_pos + kw_str.len();
            } else {
                pos = kw_pos + kw_str.len();
            }
        } else {
            break;
        }
    }
    None
}

