fn split_next_command(s: &str) -> Option<(String, String, String)> {
    let mut in_single=false;
    let mut in_double=false;
    let chars: Vec<char> = s.chars().collect();
    let mut i=0;
    while i<chars.len() {
        let c=chars[i];
        if c=='\'' && !in_double { in_single=!in_single; }
        else if c=='"' && !in_single { in_double=!in_double; }
        if !in_single && !in_double {
            if c==';' {
                let cmd = s[..i].to_string();
                let rest = s[i+1..].to_string();
                return Some((cmd, ";".to_string(), rest));
            } else if c=='\n' {
                let cmd = s[..i].to_string();
                let rest = s[i+1..].to_string();
                return Some((cmd, "\n".to_string(), rest));
            } else if c=='&' {
                if i+1<chars.len() && chars[i+1]=='&' {
                    let cmd = s[..i].to_string();
                    let rest = s[i+2..].to_string();
                    return Some((cmd, "&&".to_string(), rest));
                } else {
                    if i>0 && chars[i-1]=='>' {
                        i+=1;
                        continue;
                    }
                    let cmd = s[..i].to_string();
                    let rest = s[i+1..].to_string();
                    return Some((cmd, "&".to_string(), rest));
                }
            } else if c=='|' {
                if i+1<chars.len() && chars[i+1]=='|' {
                    let cmd = s[..i].to_string();
                    let rest = s[i+2..].to_string();
                    return Some((cmd, "||".to_string(), rest));
                } else {
                    let cmd = s[..i].to_string();
                    let rest = s[i+1..].to_string();
                    return Some((cmd, "|".to_string(), rest));
                }
            }
        }
        i+=1;
    }
    None
}

fn find_chain_end(s: &str) -> Option<usize> {
    let mut in_single=false;
    let mut in_double=false;
    let chars: Vec<char> = s.chars().collect();
    let mut i=0;
    while i<chars.len() {
        let c=chars[i];
        if c=='\'' && !in_double { in_single=!in_single; }
        else if c=='"' && !in_single { in_double=!in_double; }
        if !in_single && !in_double {
            if c==';' || c=='\n' || c=='&' {
                if c=='&' && i+1<chars.len() && chars[i+1]=='&' {
                    i+=2;
                    continue;
                }
                return Some(i);
            }
        }
        i+=1;
    }
    None
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut has_help=false;
    let mut after_dd=false;
    for arg in args.iter().skip(1) {
        if after_dd { continue; }
        if arg=="--" { after_dd=true; continue; }
        if arg=="-h" || arg=="--help" { has_help=true; break; }
    }
    if has_help { print_help(); process::exit(0); }

    let mut login_seen=0;
    let mut norc_seen=0;
    let mut c_seen=0;
    let mut version_seen=0;
    let mut file_seen=0;
    let mut command_value: Option<String>=None;
    let mut file_value: Option<String>=None;
    let mut pending_c=false;
    after_dd=false;
    let mut i=1;
    while i<args.len() {
        let arg=&args[i];
        if pending_c {
            let is_flag = matches!(arg.as_str(), "-h" | "--help" | "-l" | "--login" | "--norc" | "--version" | "-c");
            if is_flag || (arg.starts_with("-") && arg!="-") {
                let usage=build_usage(login_seen>0, norc_seen>0, true, version_seen>0);
                print_error_missing_c(&usage);
                process::exit(1);
            } else {
                command_value=Some(arg.clone());
                pending_c=false;
                i+=1;
                continue;
            }
        }
        if after_dd {
            if file_seen>=1 {
                let usage=build_usage(login_seen>0, norc_seen>0, c_seen>0, version_seen>0);
                print_error_unknown(arg, &usage);
                process::exit(1);
            } else {
                file_value=Some(arg.clone());
                file_seen+=1;
                i+=1;
                continue;
            }
        }
        if arg=="--" { after_dd=true; i+=1; continue; }
        if arg.starts_with("-c=") {
            c_seen+=1;
            if c_seen>1 {
                let usage=build_usage(login_seen>0, norc_seen>0, true, version_seen>0);
                print_error_duplicate("-c <command>", &usage);
                process::exit(1);
            }
            command_value=Some(arg[3..].to_string());
            i+=1;
            continue;
        }
        if arg.starts_with("-c") && arg.len()>2 {
            c_seen+=1;
            if c_seen>1 {
                let usage=build_usage(login_seen>0, norc_seen>0, true, version_seen>0);
                print_error_duplicate("-c <command>", &usage);
                process::exit(1);
            }
            command_value=Some(arg[2..].to_string());
            i+=1;
            continue;
        }
        match arg.as_str() {
            "-l" | "--login" => {
                login_seen+=1;
                if login_seen>1 {
                    let usage=build_usage(true, norc_seen>0, c_seen>0, version_seen>0);
                    print_error_duplicate("--login", &usage);
                    process::exit(1);
                }
                i+=1;
            },
            "--norc" => {
                norc_seen+=1;
                if norc_seen>1 {
                    let usage=build_usage(login_seen>0, true, c_seen>0, version_seen>0);
                    print_error_duplicate("--norc", &usage);
                    process::exit(1);
                }
                i+=1;
            },
            "--version" => {
                version_seen+=1;
                if version_seen>1 {
                    let usage=build_usage(login_seen>0, norc_seen>0, c_seen>0, true);
                    print_error_duplicate("--version", &usage);
                    process::exit(1);
                }
                i+=1;
            },
            "-c" => {
                c_seen+=1;
                if c_seen>1 {
                    let usage=build_usage(login_seen>0, norc_seen>0, true, version_seen>0);
                    print_error_duplicate("-c <command>", &usage);
                    process::exit(1);
                }
                pending_c=true;
                i+=1;
            },
            _ => {
                if arg.starts_with("-") {
                    let usage=build_usage(login_seen>0, norc_seen>0, c_seen>0, version_seen>0);
                    print_error_unknown(arg, &usage);
                    process::exit(1);
                } else {
                    if file_seen>=1 {
                        let usage=build_usage(login_seen>0, norc_seen>0, c_seen>0, version_seen>0);
                        print_error_unknown(arg, &usage);
                        process::exit(1);
                    } else {
                        file_value=Some(arg.clone());
                        file_seen+=1;
                        i+=1;
                    }
                }
            }
        }
    }
    if pending_c {
        let usage=build_usage(login_seen>0, norc_seen>0, true, version_seen>0);
        print_error_missing_c(&usage);
        process::exit(1);
    }
    if version_seen>0 {
        print_version();
        process::exit(0);
    }

    let norc = norc_seen>0;
    let mut shell = Shell::new();

    if !norc {
        let home = shell.vars.get("HOME").cloned().unwrap_or_else(|| dirs::home_dir().map(|p| p.to_string_lossy().to_string()).unwrap_or_else(|| "/home/agent".to_string()));
        let mut rc_files=Vec::new();
        let home_rc=format!("{}/.nshrc", home);
        if Path::new(&home_rc).exists() { rc_files.push(home_rc); }
        let xdg_home_opt = env::var_os("XDG_CONFIG_HOME");
        let xdg_rc = if let Some(xdg_home)=xdg_home_opt {
            let s=xdg_home.to_string_lossy().to_string();
            if s.is_empty() { None } else { Some(format!("{}/nsh/nshrc", s)) }
        } else {
            Some(format!("{}/.config/nsh/nshrc", home))
        };
        if let Some(p)=xdg_rc {
            if Path::new(&p).exists() { rc_files.push(p); }
        }
        for rc in rc_files {
            if let Ok(content)=fs::read_to_string(&rc) {
                shell.exec_line(&content);
            }
        }
    }

    if let Some(file)=file_value {
        if command_value.is_none() {
            match fs::read_to_string(&file) {
                Ok(content) => {
                    let code=shell.exec_line(&content);
                    process::exit(code);
                },
                Err(_) => {
                    eprintln!("nsh: panicked at src/main.rs:114:34:");
                    eprintln!("failed to open the file: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}");
                    for idx in 0..16 {
                        eprintln!("nsh:    {}:     0x{:x} - <unknown>", idx, 0x55d41e26b4fc as u64 + idx as u64);
                    }
                    eprintln!();
                    eprintln!("nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues");
                    process::exit(101);
                }
            }
        } else {
            let cmd=command_value.unwrap();
            let code=shell.exec_line(&cmd);
            process::exit(code);
        }
    } else if let Some(cmd)=command_value {
        let code=shell.exec_line(&cmd);
        process::exit(code);
    } else {
        // Check if stdout is tty
        if !std::io::stdout().is_terminal() {
            eprintln!("nsh: warning: stdout is not a tty");
            eprintln!("nsh: panicked at src/main.rs:114:34:");
            eprintln!("failed to open the file: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}");
            for idx in 0..16 {
                eprintln!("nsh:    {}:     0x{:x} - <unknown>", idx, 0x55d41e26b4fc as u64 + idx as u64);
            }
            eprintln!();
            eprintln!("nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues");
            process::exit(101);
        }
        eprintln!("nsh: panicked at src/mainloop.rs:486:20:");
        eprintln!("Formatting argument out of range");
        for idx in 0..16 {
            eprintln!("nsh:    {}:     0x{:x} - <unknown>", idx, 0x55d41e26b4fc as u64 + idx as u64);
        }
        eprintln!();
        eprintln!("nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues");
        eprint!("$ ");
        process::exit(0);
    }
}
